12	interface SettingsView {
13	  // The clerk limit, the floor, the terms, the late percent and the cap in force on the sheet's today.
14	  clerkLimit: string | null;
15	  floor: string;
16	  terms: number;
17	  latePct: string;
18	  // The date claims round by (before it half up, on or after it half to even); null when blank: the sheet's today.
19	  policyDate: string | null;
20	  // The date from which claims opened are numbered within their period; null when blank: off.
21	  periodNumberingFrom: string | null;
22	  cap: string | null;
23	  // Every value recorded for the dated settings, each from its from-date.
24	  dated: DatedSetting[];
