30	/**
31	 * One value recorded for a dated setting, in force from its from-date until the next one recorded for its key:
32	 * clerk-limit, floor, terms, terms-<grade>, late-pct, cap or proof-threshold. The value is null for none (a blank
33	 * clerk limit, cap or proof threshold).
34	 */
35	interface DatedSetting {
36	  key: string;
37	  from: string;
38	  value: string | null;
39	}
40	
41	/** A dated setting's key as the form and its fields name it. */
42	export type DatedKey = 'clerk-limit' | 'floor' | 'terms' | 'late-pct' | 'cap' | 'proof-threshold' | `terms-${string}`;
43	
44	export const ROLES = ['clerk', 'steward', 'viewer'];
45	/** The roles the permission matrix can list; a viewer may take no action. */
46	export const PERMISSION_ROLES = ['clerk', 'steward'];
47	
48	/** The actions of the permission matrix, with the roles that may take each while none are set (the standing rule). */
49	export const PERMISSIONS: readonly { action: string; standing: string }[] = [
50	  { action: 'open', standing: 'clerk,steward' },
51	  { action: 'settle', standing: 'clerk,steward' },
52	  { action: 'void', standing: 'clerk,steward' },
53	  { action: 'reassign', standing: 'steward' },
54	  { action: 'close', standing: 'clerk,steward' },
55	  { action: 'reopen', standing: 'steward' },
56	];
