58	/** Roles typed as a comma separated list, trimmed and each listed once; blank for none typed. */
59	function normalRoles(typed: string): string {
60	  const roles = typed.split(',').map((r) => r.trim());
61	  return typed.trim() ? [...new Set(roles)].join(',') : '';
62	}
