66	/** The floor a sheet starts with: in force before any is recorded. */
67	export const DEFAULT_FLOOR = '1.00';
68	
69	/** The terms a sheet starts with, in days: in force before any are recorded. */
70	export const DEFAULT_TERMS = 14;
71	
72	const DAYS = /^\d{1,5}$/;
73	
74	/** The late percent a sheet starts with: in force before any is recorded. */
75	export const DEFAULT_LATE_PCT = '0.00';
