81	/**
82	 * The value recorded for the key in force on the date: the one with the latest from-date on or before it;
83	 * undefined when none is (the setting's starting value applies), and null when the one in force is none.
84	 */
85	function valueOn(dated: readonly DatedSetting[], key: string, date: string | null): string | null | undefined {
86	  let best: DatedSetting | undefined;
87	  for (const d of dated) {
88	    if (d.key !== key || date === null || d.from > date) continue;
89	    if (!best || d.from > best.from) best = d;
90	  }
91	  return best?.value;
92	}
