94	// The active sheet's settings: the role set for each user name (any other name is a clerk); the clerk limit, the
95	// floor, the terms (the sheet's and each grade's), the late percent and the cap, each recorded from a from-date;
96	// the policy date and the period numbering from; and the permission matrix.
97	@Injectable({ providedIn: 'root' })
98	export class SettingsStore {
99	  private readonly http = inject(HttpClient);
100	  private readonly session = inject(Session);
101	
102	  readonly roles = signal<readonly RoleView[]>([]);
103	  /** Every value recorded for the dated settings. */
104	  readonly dated = signal<readonly DatedSetting[]>([]);
105	  /** The floor in force on a date: the least the live due of a claim dated on it can be. */
106	  readonly floor = computed(() => {
107	    const dated = this.dated();
108	    return (date: string | null): string => valueOn(dated, 'floor', date) ?? DEFAULT_FLOOR;
109	  });
110	  /** The late percent in force on a date: what an overdue claim dated on it gains for every full 30 days. */
111	  readonly latePct = computed(() => {
112	    const dated = this.dated();
113	    return (date: string | null): string => valueOn(dated, 'late-pct', date) ?? DEFAULT_LATE_PCT;
114	  });
115	  /** The clerk limit in force on the sheet's today; null for no limit. */
116	  readonly clerkLimit = computed(() => valueOn(this.dated(), 'clerk-limit', this.session.sheetToday()) ?? null);
117	  /** The cap in force on the sheet's today; null for none. */
118	  readonly cap = computed(() => valueOn(this.dated(), 'cap', this.session.sheetToday()) ?? null);
119	  /** The proof threshold in force on the sheet's today; null for none. */
120	  readonly proofThreshold = computed(() => valueOn(this.dated(), 'proof-threshold', this.session.sheetToday()) ?? null);
121	  /** The floor, the terms and the late percent in force on the sheet's today. */
122	  readonly floorToday = computed(() => this.floor()(this.session.sheetToday()));
123	  readonly termsToday = computed(() => this.termsFor('', this.session.sheetToday()));
124	  readonly latePctToday = computed(() => this.latePct()(this.session.sheetToday()));
125	  /** The policy date as set; null when blank. */
126	  readonly policyDate = signal<string | null>(null);
127	  /** The period numbering from as set; null when blank (off). */
128	  readonly periodNumberingFrom = signal<string | null>(null);
129	  /** The permission matrix as set, by action; an action not listed keeps the standing rule. */
130	  readonly permissions = signal<Readonly<Record<string, string>>>({});
131	  /**
132	   * What an overdue claim's late charge follows: the sheet's today and the late percent in force on the claim's
133	   * date; and the policy date in force (the sheet's today when blank), which decides how live figures round.
134	   */
135	  readonly lateness = computed(() => ({
136	    today: this.session.sheetToday(),
137	    latePct: this.latePct(),
138	    policyDate: this.policyDate() ?? this.session.sheetToday(),
139	  }));
