141	  /** Re-read the sheet's settings from the store. */
142	  async load(sheet: string): Promise<void> {
143	    this.roles.set([]);
144	    this.dated.set([]);
145	    this.policyDate.set(null);
146	    this.periodNumberingFrom.set(null);
147	    this.permissions.set({});
148	    const base = `/api/sheets/${encodeURIComponent(sheet)}`;
149	    const [roles, settings] = await Promise.all([
150	      firstValueFrom(this.http.get<RoleView[]>(`${base}/roles`)),
151	      firstValueFrom(this.http.get<SettingsView>(`${base}/settings`)),
152	    ]);
153	    if (this.session.sheetId() === sheet) {
154	      this.roles.set(roles);
155	      this.show(settings);
156	    }
157	  }
