159	  private show(s: SettingsView): void {
160	    this.dated.set(s.dated);
161	    this.policyDate.set(s.policyDate);
162	    this.periodNumberingFrom.set(s.periodNumberingFrom);
163	    this.permissions.set(s.permissions ?? {});
164	  }
