166	  async setRole(sheet: string, user: string, role: string): Promise<void> {
167	    const r = await firstValueFrom(
168	      this.http.put<RoleView>(`/api/sheets/${encodeURIComponent(sheet)}/roles/${encodeURIComponent(user)}`, { role }),
169	    );
170	    if (this.session.sheetId() === sheet) {
171	      this.roles.update((l) => [...l.filter((x) => x.user !== r.user), r].sort((a, b) => a.user.localeCompare(b.user)));
172	    }
173	  }
