175	  /**
176	   * Record a dated setting's value (null for none) from the date, or from the sheet's today when null; a value
177	   * already recorded from that date is replaced.
178	   */
179	  async setDated(sheet: string, key: DatedKey, value: string | number | null, from: string | null): Promise<void> {
180	    const path = key.startsWith('terms-') ? `grade-terms/${encodeURIComponent(key.slice('terms-'.length))}` : key;
181	    const s = await firstValueFrom(
182	      this.http.put<SettingsView>(`/api/sheets/${encodeURIComponent(sheet)}/settings/${path}`, { value, from }),
183	    );
184	    if (this.session.sheetId() === sheet) this.show(s);
185	  }
