187	  /** The terms in force on the date for the grade: its own, else the sheet's (the starting 14 before any). */
188	  termsFor(grade: string, date: string | null): number {
189	    const own = grade ? valueOn(this.dated(), `terms-${grade}`, date) : undefined;
190	    const terms = own ?? valueOn(this.dated(), 'terms', date);
191	    return terms == null ? DEFAULT_TERMS : Number(terms);
192	  }
