194	  async setPolicyDate(sheet: string, value: string | null): Promise<void> {
195	    const s = await firstValueFrom(
196	      this.http.put<SettingsView>(`/api/sheets/${encodeURIComponent(sheet)}/settings/policy-date`, { value }),
197	    );
198	    if (this.session.sheetId() === sheet) this.show(s);
199	  }
