201	  /** Set the roles that may take the action, comma separated; null (blank) for the standing rule. */
202	  async setPermission(sheet: string, action: string, value: string | null): Promise<void> {
203	    const s = await firstValueFrom(
204	      this.http.put<SettingsView>(
205	        `/api/sheets/${encodeURIComponent(sheet)}/settings/permissions/${encodeURIComponent(action)}`,
