534	  protected value(e: Event): string {
535	    return (e.target as HTMLInputElement).value;
536	  }
537	
538	  protected setGradeTermsField(grade: string, v: string): void {
539	    this.gradeTerms.update((t) => ({ ...t, [grade]: v }));
540	    this.gradeTermsChanged.add(grade);
541	    this.settingsError.set(null);
542	  }
543	
544	  protected setPermField(action: string, v: string): void {
545	    this.perms.update((p) => ({ ...p, [action]: v }));
546	    this.permsChanged.add(action);
547	    this.settingsError.set(null);
548	  }
549	
550	  protected gradeKey(grade: string): DatedKey {
551	    return `terms-${grade}`;
552	  }
553	
554	  // A from-date typed for a setting whose value field holds a value saves it from that date.
555	  protected setFrom(key: DatedKey, v: string): void {
556	    this.from.update((f) => ({ ...f, [key]: v }));
557	    this.settingsError.set(null);
558	    switch (key) {
559	      case 'clerk-limit':
560	        this.limitChanged ||= this.limit().trim() !== '';
561	        break;
562	      case 'floor':
563	        this.floorChanged ||= this.floor().trim() !== '';
564	        break;
565	      case 'terms':
566	        this.termsChanged ||= this.terms().trim() !== '';
567	        break;
568	      case 'late-pct':
569	        this.latePctChanged ||= this.latePct().trim() !== '';
570	        break;
571	      case 'cap':
572	        this.capChanged ||= this.cap().trim() !== '';
573	        break;
574	      case 'proof-threshold':
575	        this.proofThresholdChanged ||= this.proofThreshold().trim() !== '';
576	        break;
577	      default:
578	        if ((this.gradeTerms()[key.slice('terms-'.length)] ?? '').trim() !== '') {
579	          this.gradeTermsChanged.add(key.slice('terms-'.length));
580	        }
581	    }
582	  }
583	
584	  /** The from-date typed for the key, or null when blank (the sheet's today). */
585	  private fromOf(key: DatedKey): string | null {
586	    return (this.from()[key] ?? '').trim() || null;
587	  }
588	
589	  protected async saveSettings(e: Event): Promise<void> {
590	    e.preventDefault();
591	    if (this.savingSettings) {
592	      // saved once the one in flight answers, so a value typed meanwhile is not lost
593	      this.resubmit = true;
594	      return;
595	    }
596	    this.settingsError.set(null);
597	    const sheet = this.session.sheetId();
598	    if (!sheet) return;
599	    const limit = this.limit().trim();
600	    if (this.limitChanged && limit && !LIMIT.test(limit)) {
601	      this.settingsError.set('Enter a clerk limit of 0.00 or more, with up to two decimals, or leave it blank.');
602	      return;
603	    }
604	    const floor = this.floor().trim();
605	    if (this.floorChanged && !LIMIT.test(floor)) {
606	      this.settingsError.set('Enter a floor of 0.00 or more, with up to two decimals.');
607	      return;
608	    }
609	    const terms = this.terms().trim();
610	    if (this.termsChanged && !DAYS.test(terms)) {
611	      this.settingsError.set('Enter terms as a whole number of days, 0 or more.');
612	      return;
613	    }
614	    const gradeTerms = new Map<string, string>();
615	    for (const g of this.gradeTermsChanged) gradeTerms.set(g, (this.gradeTerms()[g] ?? '').trim());
616	    for (const [g, t] of gradeTerms) {
617	      if (!DAYS.test(t)) {
618	        this.settingsError.set(`Enter terms for grade ${g} as a whole number of days, 0 or more.`);
619	        return;
620	      }
621	    }
622	    const latePct = this.latePct().trim();
623	    if (this.latePctChanged && !PCT.test(latePct)) {
624	      this.settingsError.set('Enter a late percent of 0.00 or more, with up to two decimals.');
625	      return;
626	    }
627	    const policyDate = this.policyDate().trim();
628	    if (this.policyDateChanged && policyDate && !DATE.test(policyDate)) {
629	      this.settingsError.set('Enter a policy date, or leave it blank for the sheet\'s today.');
630	      return;
631	    }
632	    const periodNumberingFrom = this.periodNumberingFrom().trim();
633	    if (this.periodNumberingFromChanged && periodNumberingFrom && !DATE.test(periodNumberingFrom)) {
634	      this.settingsError.set('Enter a period numbering from date, or leave it blank for off.');
635	      return;
636	    }
637	    const cap = this.cap().trim();
638	    if (this.capChanged && cap && !LIMIT.test(cap)) {
639	      this.settingsError.set('Enter a cap of 0.00 or more, with up to two decimals, or leave it blank.');
640	      return;
641	    }
642	    const proofThreshold = this.proofThreshold().trim();
643	    if (this.proofThresholdChanged && proofThreshold && !LIMIT.test(proofThreshold)) {
644	      this.settingsError.set('Enter a proof threshold of 0.00 or more, with up to two decimals, or leave it blank.');
645	      return;
646	    }
647	    const perms = new Map<string, string>();
648	    for (const a of this.permsChanged) {
649	      const typed = (this.perms()[a] ?? '').trim();
650	      if (typed && typed.split(',').some((r) => !PERMISSION_ROLES.includes(r.trim()))) {
651	        this.settingsError.set(`List the roles that may ${a} as clerk, steward or both, separated by commas, or leave it blank.`);
652	        return;
653	      }
654	      perms.set(a, normalRoles(typed));
655	    }
656	    const keys: DatedKey[] = [];
657	    if (this.limitChanged) keys.push('clerk-limit');
658	    if (this.floorChanged) keys.push('floor');
659	    if (this.termsChanged) keys.push('terms');
660	    for (const g of gradeTerms.keys()) keys.push(`terms-${g}`);
661	    if (this.latePctChanged) keys.push('late-pct');
662	    if (this.capChanged) keys.push('cap');
663	    if (this.proofThresholdChanged) keys.push('proof-threshold');
664	    const from = new Map<DatedKey, string | null>();
665	    for (const k of keys) {
666	      const f = this.fromOf(k);
667	      if (f !== null && !DATE.test(f)) {
668	        this.settingsError.set('Enter a from-date, or leave it blank for the sheet\'s today.');
669	        return;
670	      }
671	      from.set(k, f);
672	    }
673	    this.savingSettings = true;
674	    try {
675	      if (this.limitChanged) {
676	        await this.store.setDated(sheet, 'clerk-limit', limit || null, from.get('clerk-limit') ?? null);
677	        // a value typed while it was saving stays to be saved
678	        this.limitChanged = this.limit().trim() !== limit;
679	      }
680	      if (this.floorChanged) {
681	        await this.store.setDated(sheet, 'floor', floor, from.get('floor') ?? null);
682	        this.floorChanged = this.floor().trim() !== floor;
683	      }
684	      if (this.termsChanged) {
685	        await this.store.setDated(sheet, 'terms', Number(terms), from.get('terms') ?? null);
686	        this.termsChanged = this.terms().trim() !== terms;
687	      }
688	      for (const [g, t] of gradeTerms) {
689	        await this.store.setDated(sheet, `terms-${g}`, Number(t), from.get(`terms-${g}`) ?? null);
690	        if ((this.gradeTerms()[g] ?? '').trim() === t) this.gradeTermsChanged.delete(g);
691	      }
692	      if (this.latePctChanged) {
693	        await this.store.setDated(sheet, 'late-pct', latePct, from.get('late-pct') ?? null);
694	        this.latePctChanged = this.latePct().trim() !== latePct;
695	      }
696	      if (this.policyDateChanged) {
697	        await this.store.setPolicyDate(sheet, policyDate || null);
698	        this.policyDateChanged = this.policyDate().trim() !== policyDate;
699	      }
700	      if (this.periodNumberingFromChanged) {
701	        await this.store.setPeriodNumberingFrom(sheet, periodNumberingFrom || null);
702	        this.periodNumberingFromChanged = this.periodNumberingFrom().trim() !== periodNumberingFrom;
703	      }
704	      if (this.capChanged) {
705	        await this.store.setDated(sheet, 'cap', cap || null, from.get('cap') ?? null);
706	        this.capChanged = this.cap().trim() !== cap;
707	      }
708	      if (this.proofThresholdChanged) {
709	        await this.store.setDated(sheet, 'proof-threshold', proofThreshold || null, from.get('proof-threshold') ?? null);
710	        this.proofThresholdChanged = this.proofThreshold().trim() !== proofThreshold;
711	      }
712	      for (const [a, roles] of perms) {
713	        await this.store.setPermission(sheet, a, roles || null);
714	        // roles typed while it was saving stay to be saved
715	        if (normalRoles(this.perms()[a] ?? '') === roles) this.permsChanged.delete(a);
716	      }
717	    } catch {
718	      this.resubmit = false;
719	      this.settingsError.set('Could not save the settings.');
720	    } finally {
721	      this.savingSettings = false;
722	    }
723	    if (this.resubmit) {
724	      this.resubmit = false;
725	      await this.saveSettings(e);
726	    }
727	  }
728	
729	  protected async saveRole(e: Event): Promise<void> {
730	    e.preventDefault();
731	    if (this.submitting) return;
732	    this.roleError.set(null);
733	    const sheet = this.session.sheetId();
734	    if (!sheet) return;
735	    const user = this.user().trim();
736	    const role = this.role().trim();
737	    if (!user) {
738	      this.roleError.set('Enter a user name.');
739	      return;
740	    }
741	    if (!ROLES.includes(role)) {
742	      this.roleError.set('Choose a role of clerk, steward or viewer.');
743	      return;
744	    }
745	    this.submitting = true;
746	    try {
747	      await this.store.setRole(sheet, user, role);
748	    } catch {
749	      this.roleError.set('Could not set that role.');
750	    } finally {
751	      this.submitting = false;
752	    }
753	  }
